namespace Coworkee.Cli.Spec;

/// <summary>
/// An entity a reference can point to: one of the spec, or one the app has already (<see cref="Spec"/> is null then).
/// <see cref="GeneratedDto"/>: an existing entity whose DTO Coworkee.CodeGen generates ([AutoGenerateDto]).
/// </summary>
public sealed record KnownEntity(string Module, string Name, string Plural, string? Display, EntitySpec? Spec = null, bool GeneratedDto = false);
